public class Dorfbewohner
{
   String name;
   int muskelkraft;

   public Dorfbewohner(String nameNeu, int muskelkraftNeu)
   {
      name = nameNeu;
      muskelkraft = muskelkraftNeu;
   }

   public void zaubertrankTrinken()
   {
      muskelkraft = muskelkraft * 10;
   }
}

public class Barde extends Dorfbewohner {

   public void singen()
   {
      println("Never gonna give you up, Never gonna let you down...");
   }
}
